import{_ as a,o as i,c as o,a2 as t}from"./chunks/framework.CHeM0PsO.js";const h=JSON.parse('{"title":"Explorador TUI","description":"","frontmatter":{},"headers":[],"relativePath":"es/advanced/tui.md","filePath":"es/advanced/tui.md","lastUpdated":1784903584000}'),n={name:"es/advanced/tui.md"};function d(s,e,l,r,c,u){return i(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="explorador-tui" tabindex="-1">Explorador TUI <a class="header-anchor" href="#explorador-tui" aria-label="Permalink to &quot;Explorador TUI&quot;">​</a></h1><h2 id="descripcion-general" tabindex="-1">Descripción General <a class="header-anchor" href="#descripcion-general" aria-label="Permalink to &quot;Descripción General&quot;">​</a></h2><p>swag2mcp incluye una TUI (Interfaz de Usuario de Terminal) incorporada para la exploración interactiva de APIs. Es una aplicación de terminal de pantalla completa que le permite buscar, navegar, inspeccionar e invocar endpoints de API sin salir de la terminal.</p><h2 id="inicio" tabindex="-1">Inicio <a class="header-anchor" href="#inicio" aria-label="Permalink to &quot;Inicio&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span></span></code></pre></div><p>Si no existe un archivo de configuración, la TUI iniciará automáticamente el asistente de inicialización primero.</p><h2 id="modos" tabindex="-1">Modos <a class="header-anchor" href="#modos" aria-label="Permalink to &quot;Modos&quot;">​</a></h2><p>La TUI tiene tres modos, intercambiables con la tecla <code>Tab</code>:</p><h3 id="modo-de-busqueda" tabindex="-1">Modo de búsqueda <a class="header-anchor" href="#modo-de-busqueda" aria-label="Permalink to &quot;Modo de búsqueda&quot;">​</a></h3><p>Búsqueda de texto completo en todos los endpoints de todas las especificaciones. Admite la misma sintaxis de consulta que la herramienta MCP <code>search</code>.</p><ul><li>Escriba una consulta para buscar nombres, rutas y descripciones de endpoints</li><li>Filtre resultados por método, etiqueta o ruta</li><li>Vea los detalles del endpoint con una sola pulsación de tecla</li><li>Navegue por los resultados con paginación (10 elementos por página)</li></ul><h3 id="modo-de-navegacion" tabindex="-1">Modo de navegación <a class="header-anchor" href="#modo-de-navegacion" aria-label="Permalink to &quot;Modo de navegación&quot;">​</a></h3><p>Navegación en árbol a través de la jerarquía de especificaciones:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Especificación → Colección → Etiqueta → Endpoint</span></span></code></pre></div><ul><li>Navegue hacia abajo en el árbol para encontrar endpoints específicos</li><li>Vea los detalles del endpoint (parámetros, cuerpo de solicitud, respuestas)</li><li>Invocar la API directamente desde la TUI</li><li>Guarde los detalles del endpoint como un archivo JSON</li></ul><h3 id="modo-de-autenticacion" tabindex="-1">Modo de autenticación <a class="header-anchor" href="#modo-de-autenticacion" aria-label="Permalink to &quot;Modo de autenticación&quot;">​</a></h3><p>Vea los tokens de autenticación y encabezados para cualquier especificación. Útil para depuración o generación de comandos curl.</p><h2 id="controles" tabindex="-1">Controles <a class="header-anchor" href="#controles" aria-label="Permalink to &quot;Controles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tecla</th><th>Acción</th></tr></thead><tbody><tr><td><code>↑</code> / <code>↓</code></td><td>Navegar arriba/abajo</td></tr><tr><td><code>Enter</code></td><td>Seleccionar o abrir</td></tr><tr><td><code>Esc</code></td><td>Retroceder un nivel</td></tr><tr><td><code>Tab</code></td><td>Cambiar entre los modos Búsqueda, Navegación y Autenticación</td></tr><tr><td><code>/</code></td><td>Enfocar entrada de búsqueda</td></tr><tr><td><code>N</code> / <code>P</code></td><td>Siguiente / página anterior</td></tr><tr><td><code>B</code></td><td>Volver a la pantalla anterior</td></tr><tr><td><code>M</code></td><td>Volver al menú principal</td></tr><tr><td><code>S</code></td><td>Guardar detalle del endpoint como archivo JSON</td></tr><tr><td><code>q</code> / <code>Ctrl+C</code></td><td>Salir</td></tr></tbody></table><h2 id="estados" tabindex="-1">Estados <a class="header-anchor" href="#estados" aria-label="Permalink to &quot;Estados&quot;">​</a></h2><p>La TUI pasa por estos estados a medida que navega:</p><ol><li><strong>Cargando</strong> — cargando datos del espacio de trabajo</li><li><strong>Búsqueda</strong> — modo de búsqueda con entrada de consulta</li><li><strong>Navegación</strong> — modo de navegación con lista de especificaciones</li><li><strong>Lista de Especificaciones</strong> — lista de todas las especificaciones</li><li><strong>Lista de Colecciones</strong> — colecciones dentro de una especificación</li><li><strong>Lista de Etiquetas</strong> — etiquetas dentro de una colección</li><li><strong>Lista de Endpoints</strong> — endpoints dentro de una etiqueta</li><li><strong>Detalle del Endpoint</strong> — información completa del endpoint</li><li><strong>Resultado de Invocación</strong> — resultado de la llamada a la API</li><li><strong>Error</strong> — estado de error con mensaje</li></ol><h2 id="vista-de-detalle-del-endpoint" tabindex="-1">Vista de detalle del endpoint <a class="header-anchor" href="#vista-de-detalle-del-endpoint" aria-label="Permalink to &quot;Vista de detalle del endpoint&quot;">​</a></h2><p>Cuando selecciona un endpoint, la TUI muestra:</p><ul><li>Método HTTP y ruta</li><li>URL base y URL completa</li><li>Resumen y descripción</li><li>Todos los parámetros (nombre, ubicación, tipo, requerido)</li><li>Esquema del cuerpo de solicitud (si aplica)</li><li>Códigos de respuesta y esquemas</li><li>Estado de obsolescencia</li></ul><h2 id="requisitos" tabindex="-1">Requisitos <a class="header-anchor" href="#requisitos" aria-label="Permalink to &quot;Requisitos&quot;">​</a></h2><ul><li><strong>Tamaño de terminal:</strong> Al menos 80×24 caracteres</li><li><strong>Emulador de terminal:</strong> Funciona en la mayoría de terminales modernas (iTerm2, Terminal.app, GNOME Terminal, Windows Terminal, etc.)</li><li><strong>SSH:</strong> Funciona a través de conexiones SSH</li></ul><h2 id="notas-importantes" tabindex="-1">Notas importantes <a class="header-anchor" href="#notas-importantes" aria-label="Permalink to &quot;Notas importantes&quot;">​</a></h2><ul><li><strong>Auto-inicio</strong> — si no existe un archivo de configuración, la TUI inicia automáticamente el asistente de inicialización</li><li><strong>Paginación</strong> — las listas se paginan a 10 elementos por página. Use <code>N</code> y <code>P</code> para navegar</li><li><strong>Guardar detalles del endpoint</strong> — presione <code>S</code> en la vista de detalle del endpoint para guardar el detalle completo como un archivo JSON en el directorio actual</li><li><strong>Modo de autenticación</strong> — muestra tokens y encabezados para depuración. En producción, la herramienta de autenticación puede deshabilitarse con <code>--disable-llm-auth</code></li></ul>',29)])])}const m=a(n,[["render",d]]);export{h as __pageData,m as default};
